    for(int i=1;i<argc;++i){auto real=Artwork::open(argv[i],error);CHECK(real!=nullptr);if(!real)continue;auto file=root/(std::to_string(i)+".IMG");CHECK(real->save(file.u8string(),error));auto old_file=bytes(file);DigitizeSession session;CHECK(initialize_digitize({first,second},session,error)&&rebuild_digitize_matte(session,error)&&seed(session,error)&&fit_digitize(*real,session,error)&&build_digitize_batch(*real,session,batch,error));int old_count=real->count();CHECK(real->import_batch(batch,error)==old_count&&real->save(file.u8string(),error));loaded=Artwork::open(file.u8string(),error);CHECK(loaded&&loaded->count()==old_count+2);real->undo();CHECK(real->save(file.u8string(),error)&&bytes(file)==old_file);}
